css:
:scope { width: min(100%, 980px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 12 / span 2; grid-row: 1 / span 3; font-family: var(--os-font-heading); font-size: 15px; font-weight: 400; line-height: 1.67; letter-spacing: 0.213em; text-transform: uppercase; color: var(--os-color-text); }
.gx__i2 { grid-column: 1 / span 24; grid-row: 9 / span 17; font-family: var(--os-font-heading); font-size: 16px; font-weight: 400; line-height: 1; letter-spacing: 0em; text-align: center; color: var(--os-color-text); }
.gx__i3 { grid-column: 3 / span 19; grid-row: 29 / span 8; font-family: var(--os-font-heading); font-size: 17px; font-weight: 400; line-height: 1.29; letter-spacing: 0em; text-align: center; color: var(--os-color-text); }
.gx__i4 { grid-column: 3 / span 19; grid-row: 39 / span 6; font-family: var(--os-font-heading); font-size: 17px; font-weight: 400; line-height: 1.29; letter-spacing: 0em; text-align: center; color: var(--os-color-text); }
.gx__i5 { grid-column: 3 / span 19; grid-row: 47 / span 8; font-family: var(--os-font-heading); font-size: 17px; font-weight: 400; line-height: 1.29; letter-spacing: 0em; text-align: center; color: var(--os-color-text); }
.gx__i6 { grid-column: 3 / span 19; grid-row: 57 / span 3; font-family: var(--os-font-heading); font-size: 17px; font-weight: 400; line-height: 1.29; letter-spacing: 0em; text-align: center; color: var(--os-color-text); }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i1 { font-family: var(--os-font-heading); font-size: 14px; }
  .gx__i2 { font-family: var(--os-font-heading); font-size: 14px; }
  .gx__i3 { font-family: var(--os-font-heading); font-size: 14px; }
  .gx__i4 { font-family: var(--os-font-heading); font-size: 14px; }
  .gx__i5 { font-family: var(--os-font-heading); font-size: 14px; }
  .gx__i6 { font-family: var(--os-font-heading); font-size: 14px; }
}
